// Original BASE #42: completed BytePlus Video jobs must survive provider URL expiry.
// The existing Studio writes generated bytes to private S3 when configured.
// For public generation, never allow a paid BytePlus Video dispatch without
// validated durable object-storage *configuration*. Actual cloud reachability,
// account license and end-to-end upload/download remain separate release gates.
import {objectStorageConfig} from './generation-storage.js';

export function bytePlusPublicDurableStorageReady(model,env={}){
 if(model?.kind!=='video'||model?.provider!=='BytePlus')return true;
 if(env.AI_PUBLIC_GENERATION_ENABLED!=='true')return true; // legacy owner-only pilot preserved
 return objectStorageConfig(env).configured;
}
